import { Recipe, ShoppingCategory } from '../types';

function cat(n: string): ShoppingCategory {
  const s = n.toLowerCase();
  if (/poulet|dinde|agneau|viande|jambon|bacon|lardons|chorizo|prosciutto|boeuf|kefta|cordon bleu|escalope/.test(s)) return 'Viandes';
  if (/saumon|thon|crevette|sardine|cabillaud|anchois|hareng|maquereau/.test(s)) return 'Poissons';
  if (/\blait\b|cr[eè]me|fromage|yaourt|skyr|beurre|\boeuf|\bœuf|mozza|feta|ricotta|gorgonzola|ch[eè]vre|parmesan|camembert|mascarpone|emmental|cheddar|burrata|halloumi|kiri|philadelphia/.test(s)) return 'Produits laitiers & Œufs';
  if (/farine|chapelure|\briz\b|semoule|quinoa|vermicelles|lasagne|nouilles|naan|\bpain\b|levure|\bwrap\b|gnocchi|p[aâ]tes|tortilla|panko/.test(s)) return 'Boulangerie';
  if (/carotte|courgette|tomate|potimarron|butternut|oignon|[eé]pinard|concombre|patate|pomme|brocoli|haricot|lentille|ma[iï]s|champignon|aubergine|poivron|basilic|coriandre|persil|menthe|thym|romarin|gingembre|citron|ananas|fraise|framboise|banane|[eé]chalote|pistache|noix|amande|noisette|avocat|mangue|melon|myrtille|airelle|ail/.test(s)) return 'Fruits & Légumes';
  return 'Épicerie';
}

function em(name: string, meal: string): string {
  const n = name.toLowerCase();
  if (/soupe|velout/.test(n)) return '🍲';
  if (/salade/.test(n)) return '🥗';
  if (/risotto/.test(n)) return '🍚';
  if (/p[aâ]tes|pasta/.test(n)) return '🍝';
  if (/pizza/.test(n)) return '🍕';
  if (/tarte|quiche|flan/.test(n)) return '🥧';
  if (/wrap|sandwich|croque|toast/.test(n)) return '🥪';
  if (/poulet|chicken/.test(n)) return '🍗';
  if (/saumon|thon|poisson|crevette|sardine/.test(n)) return '🐟';
  if (/gnocchi/.test(n)) return '🥔';
  if (/\briz\b/.test(n)) return '🍚';
  if (/burger|bun/.test(n)) return '🍔';
  if (/cr[eê]pe|pancake|gaufre/.test(n)) return '🥞';
  if (/curry/.test(n)) return '🍛';
  if (/oeuf|[oœ]uf|omelette/.test(n)) return '🥚';
  if (/chips|frites/.test(n)) return '🍟';
  if (/cookie/.test(n)) return '🍪';
  if (/muffin/.test(n)) return '🧁';
  if (/brownie|brookie/.test(n)) return '🍫';
  if (/chocolat/.test(n)) return '🍫';
  if (/glace|magnum|sorbet/.test(n)) return '🍦';
  if (/g[aâ]teau|cake/.test(n)) return '🎂';
  if (/biscuit|oreo/.test(n)) return '🍪';
  if (/mousse|tiramisu/.test(n)) return '🍮';
  if (/crumble/.test(n)) return '🥣';
  if (/barre|snickers|twix/.test(n)) return '🍫';
  if (/smoothie|jus|infusion|sirop/.test(n)) return '🥤';
  if (/caf[eé]|latte/.test(n)) return '☕';
  if (/donut|bagel/.test(n)) return '🍩';
  if (/tacos|nems|gyoza/.test(n)) return '🥟';
  if (/boulette|kefta/.test(n)) return '🧆';
  if (/rillette|houmous|sauce/.test(n)) return '🫙';
  if (meal === 'breakfast') return '☕';
  return '🍽️';
}

function cleanName(raw: string): string {
  let s = raw.trim();

  // Extract dish name after "ÉPISODE X —" / "EP. X —" / "N°X —" patterns
  const epM = s.match(/(?:[ÉE][Pp][Ii][Ss][Oo][Dd][Ee]|[ÉéEe][Pp]\.?\s*\d+|N[°º]\s*\d+)[^—–\-]*[—–\-]\s*(.+)/);
  if (epM) s = epM[1].trim();

  // Strip leading non-letter chars (emojis, punctuation, spaces)
  s = s.replace(/^[^a-zA-ZÀ-ÿ]+/, '').trim();
  // Strip trailing emojis, punctuation and stray quotes
  s = s.replace(/[^a-zA-ZÀ-ÿ\d)»]+$/, '').trim();
  // Remove hashtags and extra whitespace
  s = s.replace(/#\w+/g, '').replace(/\s+/g, ' ').trim();

  // Junk detection: very short, or well-known social-post phrases
  if (
    s.length < 5 ||
    /^(loved it|hello|le détail de la recette|digestive delight)/i.test(s) ||
    /^\d+\s*(?:ingr[eé]dients?|ingredients?)\s*$/i.test(s)
  ) return 'Recette Instagram';

  // Sentence-case conditions:
  // 1. Overall >55% uppercase alpha chars, OR
  // 2. First word (3+ letters) is entirely uppercase (hook phrases like "UNE FOLIE cette recette…")
  const alpha = s.replace(/[^a-zA-ZÀ-ÿ]/g, '');
  const uppers = (s.match(/[A-ZÀÂÄÉÈÊËÎÏÔÙÛÜŸŒÆ]/g) || []).length;
  const firstWord = s.split(/[\s,!?]/)[0].replace(/[^a-zA-ZÀ-ÿ]/g, '');
  const firstWordAllCaps = firstWord.length >= 3 && firstWord === firstWord.toUpperCase() && firstWord !== firstWord.toLowerCase();
  if (alpha.length >= 4 && (uppers / alpha.length > 0.55 || firstWordAllCaps)) {
    s = s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
  } else {
    // At minimum, capitalise first letter
    s = s.charAt(0).toUpperCase() + s.slice(1);
  }

  // Truncate at 65 characters
  if (s.length > 65) {
    const cut = s.lastIndexOf(' ', 62);
    s = (cut > 20 ? s.slice(0, cut) : s.slice(0, 62)) + '…';
  }

  return s || 'Recette Instagram';
}

